"""Keep the file:// preview snapshot in sync with the five HTTP JSON interfaces."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
names = ["banners", "products", "seckill", "categories", "comments"]
data = {f"data/{name}.json": json.loads((root / f"data/{name}.json").read_text(encoding="utf-8"))
        for name in names}
(root / "js/liang-mock.js").write_text(
    "/* Generated by tools/build_mock.py. Edit data/*.json, then rebuild. */\n"
    "window.LiangMockData = " + json.dumps(data, ensure_ascii=False, indent=2) + ";\n",
    encoding="utf-8")
print("Synced 5 JSON interfaces to the offline preview snapshot.")
